def transform(g):
    H,W=len(g),len(g[0])
    c=Counter(x for r in g for x in r)
    sep=max(c,key=lambda k:sum(1 for r in g if r.count(k)==W))
    def groups(line,n):
        gs=[];s=None
        for i in range(n):
            if i not in line:
                if s is None: s=i
            else:
                if s is not None: gs.append((s,i)); s=None
        if s is not None: gs.append((s,n))
        return gs
    rows={i for i in range(H) if all(x==sep for x in g[i])}
    cols={j for j in range(W) if all(g[i][j]==sep for i in range(H))}
    rg=groups(rows,H); cg=groups(cols,W)
    bg=max((k for k in c if k!=sep),key=lambda k:c[k])
    out=[]
    for r0,r1 in rg:
        row=[]
        for c0,c1 in cg:
            cnt=sum(1 for i in range(r0,r1) for j in range(c0,c1) if g[i][j] not in (sep,bg))
            row.append(1 if cnt>=2 else bg)
        out.append(row)
    return out

